-- Quản lý tài chính — Supabase schema (Postgres)
-- Chạy 2 khối: Khối A (bảng) rồi Khối B (RLS + trigger). Region khuyên dùng: Singapore.
-- Lưu ý: RLS dưới đây là mẫu rút gọn theo is_workspace_member(); khi chạy thật tạo đủ policy cho cả 16 bảng.
create extension if not exists "pgcrypto";
create table if not exists workspaces (id uuid primary key default gen_random_uuid(), owner_id uuid references auth.users(id) on delete cascade, name text not null, mode text not null check (mode in ('personal','household','team')), tax_circular text default 'TT88/2021', created_at timestamptz default now());
create table if not exists members (id uuid primary key default gen_random_uuid(), workspace_id uuid references workspaces(id) on delete cascade, user_id uuid references auth.users(id) on delete cascade, role text default 'member' check (role in ('owner','admin','member','viewer')), unique(workspace_id,user_id));
create table if not exists wallets (id uuid primary key default gen_random_uuid(), workspace_id uuid references workspaces(id) on delete cascade, name text not null, type text default 'cash', balance numeric default 0, currency text default 'VND');
create table if not exists categories (id uuid primary key default gen_random_uuid(), workspace_id uuid references workspaces(id) on delete cascade, name text not null, kind text check (kind in ('income','expense')), color text, icon text);
create table if not exists transactions (id uuid primary key default gen_random_uuid(), workspace_id uuid references workspaces(id) on delete cascade, wallet_id uuid references wallets(id) on delete set null, category_id uuid references categories(id) on delete set null, product_id uuid, variant_id uuid, imei text, type text check (type in ('income','expense','transfer')), amount numeric not null, quantity numeric default 1, unit_price numeric, cost_price numeric, profit numeric, tax_type text, tax_rate numeric, note text, date date default current_date, created_at timestamptz default now());
create table if not exists budgets (id uuid primary key default gen_random_uuid(), workspace_id uuid references workspaces(id) on delete cascade, category_id uuid references categories(id) on delete cascade, month text not null, amount numeric not null, unique(workspace_id,category_id,month));
create table if not exists goals (id uuid primary key default gen_random_uuid(), workspace_id uuid references workspaces(id) on delete cascade, name text not null, target numeric not null, saved numeric default 0, deadline date));
create table if not exists debts (id uuid primary key default gen_random_uuid(), workspace_id uuid references workspaces(id) on delete cascade, name text not null, kind text check (kind in ('borrow','lend')), amount numeric not null, paid numeric default 0, due_date date));
create table if not exists reminders (id uuid primary key default gen_random_uuid(), workspace_id uuid references workspaces(id) on delete cascade, title text not null, amount numeric, next_date date, frequency text default 'monthly'));
create table if not exists product_categories (id uuid primary key default gen_random_uuid(), workspace_id uuid references workspaces(id) on delete cascade, name text not null, color text, icon text));
create table if not exists products (id uuid primary key default gen_random_uuid(), workspace_id uuid references workspaces(id) on delete cascade, category_id uuid references product_categories(id) on delete set null, name text not null, sku text, unit text default 'cái', cost_price numeric default 0, sale_price numeric default 0, stock numeric default 0, min_stock numeric default 0));
create table if not exists product_variants (id uuid primary key default gen_random_uuid(), product_id uuid references products(id) on delete cascade, name text not null, cost_price numeric default 0, sale_price numeric default 0, stock numeric default 0));
create table if not exists product_fields (id uuid primary key default gen_random_uuid(), workspace_id uuid references workspaces(id) on delete cascade, name text not null, field_type text check (field_type in ('text','number','date','select','boolean')), required boolean default false, enabled boolean default true, options jsonb));
create table if not exists stock_movements (id uuid primary key default gen_random_uuid(), workspace_id uuid references workspaces(id) on delete cascade, product_id uuid references products(id) on delete cascade, variant_id uuid references product_variants(id) on delete set null, kind text check (kind in ('in','out')), quantity numeric not null, imei text, created_at timestamptz default now());
create table if not exists tax_payments (id uuid primary key default gen_random_uuid(), workspace_id uuid references workspaces(id) on delete cascade, tax_type text check (tax_type in ('VAT','TNCN','TNDN','mon_bai')), period text, amount numeric not null, paid boolean default false, due_date date));
create table if not exists tax_settings (id uuid primary key default gen_random_uuid(), workspace_id uuid references workspaces(id) on delete cascade unique, circular text default 'TT88/2021', vat_rate numeric default 0.01, tncn_rate numeric default 0.005, tndn_rate numeric default 0.20, mon_bai numeric default 1000000));
-- Khối B: helper + RLS mẫu + trigger trừ tồn
create or replace function is_workspace_member(wid uuid) returns boolean language sql stable as $$ select exists (select 1 from members where workspace_id=wid and user_id=auth.uid()) or exists (select 1 from workspaces where id=wid and owner_id=auth.uid()) $$;
alter table workspaces enable row level security; alter table wallets enable row level security; alter table transactions enable row level security; alter table products enable row level security; alter table stock_movements enable row level security;
create policy "members read workspaces" on workspaces for select using (is_workspace_member(id));
create policy "members manage wallets" on wallets for all using (is_workspace_member(workspace_id));
create policy "members manage transactions" on transactions for all using (is_workspace_member(workspace_id));
create policy "members manage products" on products for all using (is_workspace_member(workspace_id));
-- Trigger: khi có stock_movements kind='out', trừ tồn variant/product; kind='in' cộng tồn. Lãi = qty*(sale-cost) tính ở app (lib/utils.ts profitOf).
create or replace function apply_stock() returns trigger language plpgsql as $$ begin if new.kind='out' then update products set stock=stock-new.quantity where id=new.product_id; if new.variant_id is not null then update product_variants set stock=stock-new.quantity where id=new.variant_id; end if; else update products set stock=stock+new.quantity where id=new.product_id; if new.variant_id is not null then update product_variants set stock=stock+new.quantity where id=new.variant_id; end if; end if; return new; end $$;
drop trigger if exists trg_stock on stock_movements; create trigger trg_stock after insert on stock_movements for each row execute function apply_stock();
-- Storage bucket cho hóa đơn (tạo trong Dashboard > Storage nếu cần): invoices (private)
